import java.util.*;

public class Main {
    static int[][] child;
    static int nodeCnt;

    // 将一个采样值插入二进制字典树
    static void insert(int x) {
        int node = 0;
        for (int b = 30; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (child[node][bit] == 0) {
                child[node][bit] = nodeCnt++;
            }
            node = child[node][bit];
        }
    }

    // 查询与 x 异或能得到的最大值
    static int queryMaxXor(int x) {
        int node = 0;
        int res = 0;

        for (int b = 30; b >= 0; b--) {
            int bit = (x >> b) & 1;
            int want = bit ^ 1;

            // 优先走相反位，使当前位异或结果为 1
            if (child[node][want] != 0) {
                res |= 1 << b;
                node = child[node][want];
            } else {
                node = child[node][bit];
            }
        }

        return res;
    }

    // 计算每个采样点是否有效
    static String solveArray(int[] s) {
        int m = s.length;
        int T = 0;  // 阈值（序列最大值）

        for (int x : s) {
            T = Math.max(T, x);
        }

        // 最多 m * 31 个节点，0 号节点作为根
        child = new int[m * 31 + 5][2];
        nodeCnt = 1;

        char[] ans = new char[m];
        Arrays.fill(ans, '0');

        // 从右往左维护后缀字典树
        for (int p = m - 1; p >= 0; p--) {
            if (p < m - 1) {
                int best = queryMaxXor(s[p]);
                if (best >= T) {
                    ans[p] = '1';
                }
            }

            // 当前采样值插入，供左侧采样点查询
            insert(s[p]);
        }

        return new String(ans);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int m = sc.nextInt();
        int[] s = new int[m];

        for (int p = 0; p < m; p++) {
            s[p] = sc.nextInt();
        }

        System.out.println(solveArray(s));
    }
}
